/**
 * Build extension/src/main.bundle.js
 * Menggabungkan picker.js + main.js (ES module, untuk test) menjadi
 * SATU file skrip klasik agar bisa disuntikkan service worker lewat
 * chrome.scripting.executeScript({ world: "MAIN" }).
 *
 * Kenapa perlu: memuat main.js lewat <script src="chrome-extension://">
 * dari halaman memicu error Blink "Unsafe attempt to load URL ...
 * Domains, protocols and ports must match" di sebagian frame.
 * File yang disuntikkan chrome.scripting bukan muatan halaman,
 * jadi error itu tidak bisa terjadi, dan web_accessible_resources
 * tidak diperlukan.
 *
 * Jalankan: node tools/build-bundle.mjs
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const PICKER = join(root, "extension/src/picker.js");
const MAIN = join(root, "extension/src/main.js");
export const BUNDLE_OUT = join(root, "extension/src/main.bundle.js");

function stripExports(code, label) {
  let out = code
    // buang baris import antar-file lokal (digabung manual di sini)
    .replace(/^import\s[^;]+from\s+["']\.\/[^"']+["'];?\s*$/gm, "")
    // export const/function/async function/class/let -> deklarasi biasa
    .replace(/^export\s+(?=(?:async\s+)?function\b|const\b|let\b|var\b|class\b)/gm, "")
    // export { ... } tidak dipakai di repo ini; gagalkan bila muncul
    ;
  if (/^export\s/m.test(out)) throw new Error(`${label}: masih ada 'export' yang tidak tertangani`);
  if (/^import\s/m.test(out)) throw new Error(`${label}: masih ada 'import' yang tidak tertangani`);
  return out;
}

function topLevelNames(code) {
  const names = new Set();
  const re = /^(?:async\s+)?function\s+([A-Za-z_$][\w$]*)|^const\s+([A-Za-z_$][\w$]*)|^let\s+([A-Za-z_$][\w$]*)/gm;
  let m;
  while ((m = re.exec(code))) names.add(m[1] || m[2] || m[3]);
  return names;
}

export function buildBundle(pickerCode, mainCode) {
  const picker = stripExports(pickerCode, "picker.js");
  const main = stripExports(mainCode, "main.js");
  const dupes = [...topLevelNames(picker)].filter((n) => topLevelNames(main).has(n));
  if (dupes.length) throw new Error(`Nama top-level bentrok picker vs main: ${dupes.join(", ")}`);
  return [
    "// GENERATED by tools/build-bundle.mjs — JANGAN EDIT FILE INI.",
    "// Sumber: extension/src/picker.js + extension/src/main.js",
    "// File klasik (bukan module) agar bisa di-inject chrome.scripting ke MAIN world.",
    "(() => {",
    '"use strict";',
    picker.trim(),
    "",
    main.trim(),
    "})();",
    "",
  ].join("\n");
}

const isCli = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isCli) {
  const bundle = buildBundle(readFileSync(PICKER, "utf8"), readFileSync(MAIN, "utf8"));
  writeFileSync(BUNDLE_OUT, bundle);
  console.log(`bundle ditulis: ${BUNDLE_OUT} (${bundle.length} bytes)`);
}
